"""
Migrate OB buckets from old VPS to new VPS.
Reads from pulse output data, holds on new OB.
"""
import urllib.request, ssl, json, time

ctx = ssl.create_default_context()
ctx.check_hostname = False
ctx.verify_mode = ssl.CERT_NONE

NEW_OB = 'http://47.84.92.71:8002/mcp'
H = {'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream'}

def ob_session(url):
    body = json.dumps({'jsonrpc':'2.0','id':1,'method':'initialize',
        'params':{'protocolVersion':'2024-11-05','capabilities':{},'clientInfo':{'name':'migrate','version':'1'}}})
    req = urllib.request.Request(url, data=body.encode(), headers=H)
    r = urllib.request.urlopen(req, context=ctx, timeout=15)
    sid = r.headers.get('Mcp-Session-Id','')
    h = {**H, 'Mcp-Session-Id': sid}
    init = json.dumps({'jsonrpc':'2.0','method':'notifications/initialized'})
    urllib.request.urlopen(urllib.request.Request(url, data=init.encode(), headers=h, method='POST'), context=ctx, timeout=5)
    return h

def hold(h, content, tags='', importance=5, pinned=False, valence=-1, arousal=-1):
    args = {'content': content, 'importance': importance}
    if tags: args['tags'] = tags
    if pinned: args['pinned'] = True
    if valence >= 0: args['valence'] = valence
    if arousal >= 0: args['arousal'] = arousal
    body = json.dumps({'jsonrpc':'2.0','id':2,'method':'tools/call','params':{'name':'hold','arguments':args}})
    req = urllib.request.Request(NEW_OB, data=body.encode(), headers=h)
    try:
        r = urllib.request.urlopen(req, context=ctx, timeout=20)
        t = r.read().decode('utf-8')
        for line in t.split('\n'):
            if line.startswith('data:'):
                d = json.loads(line[5:])
                if 'result' in d:
                    return d['result']['content'][0]['text'][:100]
    except Exception as e:
        return f'ERROR: {e}'
    return 'unknown'

